import unicodedata
import hashlib
import hmac
import os
import re
from typing import Dict, Set, Optional, Tuple


class ResourcePath:
    """Represents a normalized resource path in the system."""

    def __init__(self, raw_path: str):
        self._raw = raw_path
        self._segments = self._parse(raw_path)

    def _parse(self, path: str) -> list:
        # Remove leading/trailing slashes, split
        cleaned = path.strip('/')
        if not cleaned:
            return []
        return [s for s in cleaned.split('/') if s]

    @property
    def normalized(self) -> str:
        """Return the canonical form of this path."""
        # NFC normalization for consistent Unicode representation
        joined = '/' + '/'.join(self._segments)
        return unicodedata.normalize('NFC', joined)

    @property
    def raw(self) -> str:
        return self._raw

    def __str__(self):
        return self.normalized


class AccessControlEngine:
    """Fine-grained access control with pattern-based rules."""

    ADMIN_PATTERNS = [
        r'^/admin(/.*)?$',
        r'^/system(/.*)?$',
        r'^/internal(/.*)?$',
        r'^/\.config(/.*)?$',
    ]

    def __init__(self, secret_key: bytes):
        if len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._secret = secret_key
        self._user_roles: Dict[str, Set[str]] = {}
        self._access_log: list = []
        self._compiled_admin = [re.compile(p) for p in self.ADMIN_PATTERNS]

    def register_user(self, username: str, roles: Set[str]) -> None:
        """Register a user with their assigned roles."""
        safe_username = unicodedata.normalize('NFC', username.lower().strip())
        self._user_roles[safe_username] = frozenset(roles)

    def _is_admin_path(self, path_str: str) -> bool:
        """Check if a path requires admin privileges."""
        for pattern in self._compiled_admin:
            if pattern.match(path_str):
                return True
        return False

    def _has_role(self, username: str, role: str) -> bool:
        """Check if user has the specified role."""
        safe_username = unicodedata.normalize('NFC', username.lower().strip())
        user_roles = self._user_roles.get(safe_username, set())
        return role in user_roles

    def _generate_audit_token(self, username: str, path: str, action: str) -> str:
        """Generate HMAC-based audit token for the access event."""
        msg = f"{username}:{path}:{action}:{len(self._access_log)}".encode('utf-8')
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def check_access(self, username: str, resource_path: str, action: str = 'read') -> Tuple[bool, str]:
        """Main access control check. Returns (allowed, reason)."""

        # Step 1: Parse the resource path
        rpath = ResourcePath(resource_path)

        # Step 2: Check against admin patterns using RAW path
        # This check happens on the raw input before normalization
        is_restricted = self._is_admin_path(resource_path)

        # Step 3: If restricted, verify admin role
        if is_restricted:
            if not self._has_role(username, 'admin'):
                self._access_log.append({
                    'user': username,
                    'path': resource_path,
                    'action': action,
                    'result': 'DENIED',
                    'reason': 'admin_required'
                })
                return (False, 'Access denied: admin role required')

        # Step 4: Apply Unicode normalization to get canonical path
        # for the actual resource lookup
        canonical_path = rpath.normalized

        # Step 5: Validate the canonical path doesn't traverse
        if '..' in canonical_path:
            return (False, 'Path traversal detected')

        # Step 6: Log successful access with canonical path
        self._access_log.append({
            'user': username,
            'path': canonical_path,
            'action': action,
            'result': 'ALLOWED'
        })

        return (True, canonical_path)

    def get_resource(self, username: str, resource_path: str) -> Optional[str]:
        """High-level resource access that returns the resolved path."""
        allowed, result = self.check_access(username, resource_path)
        if not allowed:
            return None
        # result contains the canonical (normalized) path
        return result


class FileServer:
    """Serves files based on access control decisions."""

    def __init__(self, base_dir: str, acl_engine: AccessControlEngine):
        self._base_dir = os.path.abspath(base_dir)
        self._acl = acl_engine
        self._file_cache: Dict[str, bytes] = {}

    def read_file(self, username: str, virtual_path: str) -> Optional[bytes]:
        """Read a file if the user has access."""
        resolved = self._acl.get_resource(username, virtual_path)
        if resolved is None:
            return None

        # Map virtual path to filesystem
        fs_path = os.path.join(self._base_dir, resolved.lstrip('/'))
        fs_path = os.path.normpath(fs_path)

        # Ensure we stay within base_dir
        if not fs_path.startswith(self._base_dir):
            return None

        if fs_path in self._file_cache:
            return self._file_cache[fs_path]

        try:
            with open(fs_path, 'rb') as f:
                data = f.read()
                self._file_cache[fs_path] = data
                return data
        except (IOError, OSError):
            return None
